/**
 * The Fee Tracker mark (assets/brand, generated by scripts/build-brand.mjs):
 * a bold F whose third line is a check. `white` is for the teal hero and
 * splash, `teal` for light surfaces. Decorative: the text beside it carries
 * the meaning, so it is hidden from TalkBack.
 */
import { Image, type ImageStyle, type StyleProp } from 'react-native';

const SOURCES = {
  white: require('../../../assets/brand/mark-white.png'),
  teal: require('../../../assets/brand/mark.png'),
} as const;

export function BrandMark({
  size = 40,
  variant = 'white',
  style,
}: {
  size?: number;
  variant?: keyof typeof SOURCES;
  style?: StyleProp<ImageStyle>;
}) {
  return (
    <Image
      source={SOURCES[variant]}
      accessibilityElementsHidden
      importantForAccessibility="no-hide-descendants"
      resizeMode="contain"
      style={[{ width: size, height: size }, style]}
    />
  );
}
